import { 
  View, 
  Text, 
  Pressable, 
  ScrollView, 
  FlatList{{#if (eq styling "stylesheet")}}, 
  StyleSheet{{/if}} 
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
{{#if (eq icons "lucide")}}
import { ChevronLeft, ChevronRight, Plus } from 'lucide-react-native';
{{/if}}
import { EventItem } from '../../components/EventItem';

const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const events = [
  { id: '1', title: 'Team Standup', time: '9:00 AM - 9:30 AM', color: '#2563EB', location: 'Zoom' },
  { id: '2', title: 'Design Review', time: '11:00 AM - 12:00 PM', color: '#8B5CF6', location: 'Room A' },
  { id: '3', title: 'Lunch with Sarah', time: '12:30 PM - 1:30 PM', color: '#10B981', location: 'Cafe' },
  { id: '4', title: 'Sprint Planning', time: '3:00 PM - 4:00 PM', color: '#F59E0B', location: 'Conference Room' },
];

function getDaysInMonth(year{{#if typescript}}: number{{/if}}, month{{#if typescript}}: number{{/if}}) {
  return new Date(year, month + 1, 0).getDate();
}

function getFirstDayOfMonth(year{{#if typescript}}: number{{/if}}, month{{#if typescript}}: number{{/if}}) {
  return new Date(year, month, 1).getDay();
}

export default function CalendarScreen() {
  const today = new Date();
  const year = today.getFullYear();
  const month = today.getMonth();
  const todayDate = today.getDate();
  const daysInMonth = getDaysInMonth(year, month);
  const firstDay = getFirstDayOfMonth(year, month);

  const calendarDays = [];
  for (let i = 0; i < firstDay; i++) {
    calendarDays.push(null);
  }
  for (let i = 1; i <= daysInMonth; i++) {
    calendarDays.push(i);
  }

  return (
    <SafeAreaView {{#if (eq styling "nativewind")}}className="flex-1 bg-gray-50"{{else}}style={styles.safeArea}{{/if}} edges={['top']}>
      <ScrollView>
        {/* Header */}
        <View {{#if (eq styling "nativewind")}}className="flex-row items-center justify-between px-5 pt-4 pb-3"{{else}}style={styles.header}{{/if}}>
          <Text {{#if (eq styling "nativewind")}}className="text-2xl font-bold text-gray-900"{{else}}style={styles.headerTitle}{{/if}}>
            Calendar
          </Text>
          {{#if (eq icons "lucide")}}
          <Pressable {{#if (eq styling "nativewind")}}className="h-10 w-10 items-center justify-center rounded-full bg-blue-600"{{else}}style={styles.addButton}{{/if}}>
            <Plus size={20} color="#FFFFFF" />
          </Pressable>
          {{/if}}
        </View>

        {/* Month Navigation */}
        <View {{#if (eq styling "nativewind")}}className="flex-row items-center justify-between px-5 py-3"{{else}}style={styles.monthNav}{{/if}}>
          {{#if (eq icons "lucide")}}
          <Pressable {{#if (eq styling "nativewind")}}className="h-8 w-8 items-center justify-center rounded-full bg-white"{{else}}style={styles.navButton}{{/if}}>
            <ChevronLeft size={20} color="#374151" />
          </Pressable>
          {{/if}}
          <Text {{#if (eq styling "nativewind")}}className="text-lg font-semibold text-gray-900"{{else}}style={styles.monthTitle}{{/if}}>
            {MONTHS[month]} {year}
          </Text>
          {{#if (eq icons "lucide")}}
          <Pressable {{#if (eq styling "nativewind")}}className="h-8 w-8 items-center justify-center rounded-full bg-white"{{else}}style={styles.navButton}{{/if}}>
            <ChevronRight size={20} color="#374151" />
          </Pressable>
          {{/if}}
        </View>

        {/* Day Names */}
        <View {{#if (eq styling "nativewind")}}className="flex-row px-5"{{else}}style={styles.dayNames}{{/if}}>
          {DAYS.map((day) => (
            <View key={day} {{#if (eq styling "nativewind")}}className="flex-1 items-center"{{else}}style={styles.dayNameContainer}{{/if}}>
              <Text {{#if (eq styling "nativewind")}}className="text-xs font-medium text-gray-400"{{else}}style={styles.dayName}{{/if}}>
                {day}
              </Text>
            </View>
          ))}
        </View>

        {/* Calendar Grid */}
        <View {{#if (eq styling "nativewind")}}className="flex-row flex-wrap px-5"{{else}}style={styles.grid}{{/if}}>
          {calendarDays.map((day, index) => (
            <Pressable
              key={index}
              {{#if (eq styling "nativewind")}}className={`w-[14.28%] aspect-square items-center justify-center ${day === todayDate ? 'bg-blue-600 rounded-full' : ''}`}{{else}}style={[styles.dayCell, day === todayDate && styles.dayCellActive]}{{/if}}
            >
              {day && (
                <Text {{#if (eq styling "nativewind")}}className={`text-sm ${day === todayDate ? 'font-semibold text-white' : 'text-gray-700'}`}{{else}}style={[styles.dayText, day === todayDate && styles.dayTextActive]}{{/if}}>
                  {day}
                </Text>
              )}
            </Pressable>
          ))}
        </View>

        {/* Events */}
        <View {{#if (eq styling "nativewind")}}className="mt-6"{{else}}style={styles.eventsSection}{{/if}}>
          <Text {{#if (eq styling "nativewind")}}className="px-5 text-lg font-bold text-gray-900"{{else}}style={styles.eventsTitle}{{/if}}>
            Today's Events
          </Text>
          <View {{#if (eq styling "nativewind")}}className="mt-3 gap-3 px-5"{{else}}style={styles.eventsList}{{/if}}>
            {events.map((event) => (
              <EventItem key={event.id} event={event} />
            ))}
          </View>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
}

{{#if (eq styling "stylesheet")}}
const styles = StyleSheet.create({
  safeArea: {
    flex: 1,
    backgroundColor: '#F9FAFB',
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 20,
    paddingTop: 16,
    paddingBottom: 12,
  },
  headerTitle: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#111827',
  },
  addButton: {
    height: 40,
    width: 40,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 20,
    backgroundColor: '#2563EB',
  },
  monthNav: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 20,
    paddingVertical: 12,
  },
  navButton: {
    height: 32,
    width: 32,
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: 16,
    backgroundColor: '#FFFFFF',
  },
  monthTitle: {
    fontSize: 18,
    fontWeight: '600',
    color: '#111827',
  },
  dayNames: {
    flexDirection: 'row',
    paddingHorizontal: 20,
  },
  dayNameContainer: {
    flex: 1,
    alignItems: 'center',
  },
  dayName: {
    fontSize: 12,
    fontWeight: '500',
    color: '#9CA3AF',
  },
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    paddingHorizontal: 20,
  },
  dayCell: {
    width: '14.28%',
    aspectRatio: 1,
    alignItems: 'center',
    justifyContent: 'center',
  },
  dayCellActive: {
    backgroundColor: '#2563EB',
    borderRadius: 20,
  },
  dayText: {
    fontSize: 14,
    color: '#374151',
  },
  dayTextActive: {
    fontWeight: '600',
    color: '#FFFFFF',
  },
  eventsSection: {
    marginTop: 24,
  },
  eventsTitle: {
    paddingHorizontal: 20,
    fontSize: 18,
    fontWeight: 'bold',
    color: '#111827',
  },
  eventsList: {
    marginTop: 12,
    gap: 12,
    paddingHorizontal: 20,
  },
});
{{/if}}

import { View, Text, Pressable{{#if (eq styling "stylesheet")}}, StyleSheet{{/if}} } from 'react-native';
{{#if (eq icons "lucide")}}
import { MapPin } from 'lucide-react-native';
{{/if}}
{{#if typescript}}
type CalendarEvent = {
  title: string;
  time: string;
  color: string;
  location: string;
};
{{/if}}

export function EventItem({ event }{{#if typescript}}: { event: CalendarEvent }{{/if}}) {
  return (
    <Pressable {{#if (eq styling "nativewind")}}className="flex-row rounded-xl bg-white p-4"{{else}}style={styles.container}{{/if}}>
      <View {{#if (eq styling "nativewind")}}className="mr-3 w-1 rounded-full"{{else}}style={[styles.colorBar, { backgroundColor: event.color }]}{{/if}} />
      <View {{#if (eq styling "nativewind")}}className="flex-1"{{else}}style={styles.content}{{/if}}>
        <Text {{#if (eq styling "nativewind")}}className="text-base font-semibold text-gray-900"{{else}}style={styles.title}{{/if}}>
          {event.title}
        </Text>
        <Text {{#if (eq styling "nativewind")}}className="mt-1 text-sm text-gray-500"{{else}}style={styles.time}{{/if}}>
          {event.time}
        </Text>
        {{#if (eq icons "lucide")}}
        <View {{#if (eq styling "nativewind")}}className="mt-2 flex-row items-center"{{else}}style={styles.locationRow}{{/if}}>
          <MapPin size={14} color="#9CA3AF" />
          <Text {{#if (eq styling "nativewind")}}className="ml-1 text-xs text-gray-400"{{else}}style={styles.location}{{/if}}>
            {event.location}
          </Text>
        </View>
        {{/if}}
      </View>
    </Pressable>
  );
}

{{#if (eq styling "stylesheet")}}
const styles = StyleSheet.create({
  container: {
    flexDirection: 'row',
    borderRadius: 12,
    backgroundColor: '#FFFFFF',
    padding: 16,
  },
  colorBar: {
    width: 4,
    borderRadius: 2,
  },
  content: {
    flex: 1,
  },
  title: {
    fontSize: 16,
    fontWeight: '600',
    color: '#111827',
  },
  time: {
    marginTop: 4,
    fontSize: 14,
    color: '#6B7280',
  },
  locationRow: {
    marginTop: 8,
    flexDirection: 'row',
    alignItems: 'center',
  },
  location: {
    marginLeft: 4,
    fontSize: 12,
    color: '#9CA3AF',
  },
});
{{/if}}
